import{z as o,x as A,o as t,c as m,q as r,j as B,D as e,d as l,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Black–Scholes 作为均衡结果","description":"","frontmatter":{"title":"Black–Scholes 作为均衡结果","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bs-as-equilibrium.md","filePath":"econ/bs-as-equilibrium.md","lastUpdated":1791063341000}'),b={name:"econ/bs-as-equilibrium.md"};function d(p,a,u,h,c,D){const i=A("Mermaid");return t(),m("div",null,[a[2]||(a[2]=r('<h1 id="black–scholes-作为均衡结果" tabindex="-1">Black–Scholes 作为均衡结果 <a class="header-anchor" href="#black–scholes-作为均衡结果" aria-label="Permalink to &quot;Black–Scholes 作为均衡结果&quot;">​</a></h1><div class="epigraph"><p>复制给出与偏好无关的期权价格；同一公式也可以从均衡核推出——当核使股票在 $\\mathbb{Q}$ 下成为漂移为 $r$ 的几何布朗。</p><footer>—— Black and Scholes, The Pricing of Options and Corporate Liabilities, Journal of Political Economy, 1973；对照 Rubinstein, Econometrica 1976</footer></div><p><a href="/econ/cir-general-equilibrium">上一课</a>用均衡核给债券定价。本课缺口是期权：Black–Scholes 首先是<strong>复制</strong>（完全市场、几何布朗），价格不含 \\(\\mu\\)；它也可以是<strong>均衡</strong>（Rubinstein 等），当代表性 \\(m\\) 恰好与对数正态相容。不把公式当成交易手册，不估计隐含波动率曲面——曲面是量化栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>动态完备：股票 \\(+\\) 债券、一个布朗、连续交易，欧式期权可复制。复制成本满足 BS PDE，边界为支付。Girsanov 把 \\(\\mu\\) 扭掉，价格是 \\(\\mathrm{E}^{\\mathbb{Q}}[\\mathrm{e}^{-rT}(S_T-K)^+]\\)。这是 FTAP，不需要 \\(u\\)。均衡问题：何种经济使 \\(S\\) 真是几何布朗、使 \\(\\mathbb{Q}\\) 存在且波动为常数？Rubinstein（1976）：离散时间、加总 CRRA、总财富对数正态，得到类似公式。连续时间里，Lucas 树加合适的果实过程也可以对齐。缺口是分层：复制价是无套利价；均衡说明这个无套利价能在某个出清里被选出来，且 \\(\\sigma\\) 从哪来。</p><p>与信息：若知情交易让 \\(\\sigma\\) 变成 Kyle 的 \\(\\lambda\\) 过程，几何布朗失败，BS 不是均衡对象。本课公共信息、对称、扩散常数。</p><p><span class="marginnote">Black and Scholes, <em>JPE</em> 81(3), 1973。Merton 同年把公式放到连续时间套利语言。Rubinstein, <em>Econometrica</em> 1976，是加总均衡路线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>复制路线：预算课的 \\(\\theta\\) 选成对冲比率 \\(\\Delta=P_S\\)，财富跟踪期权，初始财富即价格。均衡路线：\\(m\\) 给出 \\(\\mathbb{Q}\\)，\\(S\\) 在 \\(\\mathbb{Q}\\) 下的分布若是对数正态（漂移 \\(r\\)），积分得出同一公式。两条路在完全市场重合。不完全（跳、随机波动）复制失败，均衡仍可给一个价格（选出一个 \\(m\\)），或只给区间——下一课。</p>',9)),(t(),B(n,null,{default:e(()=>[s(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMP%5B%22%E5%AE%8C%E5%85%A8%20%2B%20%E5%87%A0%E4%BD%95%E5%B8%83%E6%9C%97%22%5D%20--%3E%20REP%5B%22%E5%A4%8D%E5%88%B6%3A%20%E4%BB%B7%E6%A0%BC%E4%B8%8D%E5%90%AB%20%CE%BC%22%5D%0A%20%20EQ%5B%22%E5%9D%87%E8%A1%A1%20m%20%E9%80%89%E5%87%BA%20Q%22%5D%20--%3E%20DIST%5B%22S%20%E5%9C%A8%20Q%20%E4%B8%8B%E5%AF%B9%E6%95%B0%E6%AD%A3%E6%80%81%22%5D%0A%20%20DIST%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%20BS%20%E5%85%AC%E5%BC%8F%22%5D%0A%20%20REP%20--%3E%20SAME%0A%20%20JUMP%5B%22%E8%B7%B3%20%2F%20%E9%9A%8F%E6%9C%BA%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20INC%5B%22%E4%B8%8D%E5%AE%8C%E5%85%A8%3A%20%E4%B8%8B%E4%B8%80%E8%AF%BE%E7%9A%84%E7%95%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要把 \\(\\Delta\\) 对冲写成「每个 tick 再平衡」。连续是理想；价差下精确复制不可能，Constantinides 后课。本课零成本。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：对冲比率 \\(\\Delta\\) 就是「期权价格对股价的敏感度」——股价涨 1 元，期权约涨 \\(\\Delta\\) 元。持有 1 份期权再卖空 \\(\\Delta\\) 份股票，两者的涨跌互相抵消，组合对股价的小幅波动暂时免疫。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"复制的机制是张成：期权的扩散暴露用股票对冲掉，剩余是无风险，必须赚 \\(r\\)，否则套利。均衡的机制是 \\(m\\) 倾斜 \\(\\mathbb{P}\\) 到 \\(\\mathbb{Q}\\)：风险厌恶改变的是 \\(\\mu\\) 与 \\(r\\) 的差（股权溢价），不改变复制需要的 \\(\\sigma\\)。所以偏好进入股票的超额，不进入已复制期权相对股票的价格——这正是 BS 令人吃惊之处。CIR 对债券也是 \\(\\mathbb{Q}\\)–期望；债券支付确定，期权支付非线性，但对偶相同。",-1)),a[7]||(a[7]=E("p",null,"公司负债：BS 原文把股权当看涨。那是对资本结构的或有要求权语言，接 MM 的切片，不是本课展开。点到：同一公式，支付换成 \\(\\max(V-D,0)\\)。",-1)),a[8]||(a[8]=E("p",null,[E("span",{class:"marginnote"},"Breeden–Litzenberger：期权价格对 \\(K\\) 的二阶导恢复风险中性密度。那是从价格读 \\(q\\)，测量偏量化；理论上确认 BS 对应对数正态 \\(\\mathbb{Q}\\)。")],-1)),(t(),B(n,null,{default:e(()=>[s(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22%E6%9C%9F%E6%9D%83%3A%20%E6%94%AF%E4%BB%98%E9%9D%9E%E7%BA%BF%E6%80%A7%2C%20%E5%B8%A6%E6%89%A9%E6%95%A3%E6%9A%B4%E9%9C%B2%22%5D%20--%3E%20HEDGE%5B%22%E7%94%A8%20%CE%94%20%E4%BB%BD%E8%82%A1%E7%A5%A8%E5%81%9A%E5%8F%8D%E5%90%91%E5%AF%B9%E5%86%B2%22%5D%0A%20%20HEDGE%20--%3E%20NET%5B%22%E5%87%80%E6%89%A9%E6%95%A3%E6%9A%B4%E9%9C%B2%E8%A2%AB%E6%B6%88%E6%88%90%E9%9B%B6%22%5D%0A%20%20NET%20--%3E%20RF%5B%22%E6%AE%8B%E4%BD%99%E7%BB%84%E5%90%88%E5%AE%8C%E5%85%A8%E6%97%A0%E9%A3%8E%E9%99%A9%22%5D%0A%20%20RF%20--%3E%20ROR%5B%22%E5%8F%AA%E8%83%BD%E6%81%B0%E5%A5%BD%E8%B5%9A%20r%2C%20%E5%A4%9A%E8%B5%9A%E5%B0%91%E8%B5%9A%E9%83%BD%E8%A2%AB%E5%A5%97%E5%88%A9%E6%8A%B9%E5%B9%B3%22%5D%0A%20%20ROR%20--%3E%20OUT%5B%22%E4%BB%B7%E6%A0%BC%E9%87%8C%E5%8F%AA%E5%89%A9%20r%20%E4%B8%8E%20%CF%83%2C%20%CE%BC%20%E8%A2%AB%E6%8C%A4%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=r('<p>这张图回答的是：偏好为什么进不了已复制期权的价格。对冲把期权拆成「股票暴露 + 无风险余额」，无风险余额的收益率被套利钉在 \\(r\\) 上——整条链路里没有任何一步需要知道投资者怕不怕风险（\\(u\\)、\\(\\mu\\)），这就是「复制价与偏好无关」的机制版本。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>隐含波动率微笑表示几何布朗被拒绝，不是 FTAP 被拒绝——市场仍可能无套利，只是 \\(\\mathbb{Q}\\) 下不是对数正态。下一课不完全：没有唯一 \\(\\mathbb{Q}\\) 时，期权落在超复制与次复制之间。BS 是完全端的点。</p><p>后课默认：BS 是完全市场复制价，也可由相容均衡选出。价格不含 \\(\\mu\\)，含 \\(r\\) 与 \\(\\sigma\\)。不是交易规程，不是波动率曲面实证。</p><p><span class="marginnote">常见误区：把「BS 给出价格」读成「BS 给出真实世界的概率」。公式里的期望取在风险中性测度 \\(\\mathbb{Q}\\) 下——先把所有人假想成风险中性再算平均；真实的怕风险程度没有消失，只是被折进了 \\(r\\) 与股价本身。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完全 + 几何布朗：期权可复制，价格是 \\(\\mathbb{Q}\\)–期望，与 \\(u\\) 无关。</li><li>均衡给出使该 \\(\\mathbb{Q}\\) 出现的 \\(m\\)；溢价在股票里，不在已复制的相对价格里。</li><li>跳与随机波动破坏精确复制。</li><li>出处：Black and Scholes, <em>JPE</em> 1973；Rubinstein, <em>Econometrica</em> 1976。</li></ul>',7))])}const T=o(b,[["render",d]]);export{S as __pageData,T as default};
